def postorder(root):
    out = []

    def walk(node):
        if node is None:
            return
        walk(node.left)        # left
        walk(node.right)       # right
        out.append(node.val)   # root

    walk(root)
    return out

def postorder(root):
    if root is None:
        return []
    out, stack = [], [root]
    while stack:
        node = stack.pop()
        out.append(node.val)
        if node.left is not None:
            stack.append(node.left)    # left first so right pops first
        if node.right is not None:
            stack.append(node.right)
    out.reverse()                      # root,right,left -> left,right,root
    return out

def postorder(root):
    out, stack, last = [], [], None
    node = root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        peek = stack[-1]
        if peek.right is not None and peek.right is not last:
            node = peek.right          # right subtree still to do
        else:
            out.append(peek.val)
            last = stack.pop()
    return out
